//log security event
java.util.Map<String, String> logMap = new java.util.HashMap<>();
logMap.put("reportID", myStepPage.getString("pzInsKey"));
logMap.put("reportName", myStepPage.getString("pyLabel"));
logMap.put("reportClass", myStepPage.getString("pxInsName").split("!")[0]);
String outcome = com.pega.pegarules.pub.security.SecurityEventConstants.FAILURE;
PegaAPI pegaapi = (PegaAPI)tools;
pegaapi.getSecurityEventLogger().logDataAccessEvent(tools, com.pega.pegarules.pub.security.SecurityEventConstants.RDEXECUTION, outcome, 
                                             null, logMap);
///up to here-- satish added to log RD execution failure

String  messageParams = "pyRuleExecutionNoAccess" + "\t" + myStepPage.getString("pzInsKey") ;  

String strError = tools.getRuleMessage(messageParams );

StringMap  keys = new HashStringMap();
keys.putString("pxObjClass", "Rule-Obj-HTML");
keys.putString("pyStreamName", "ShowMessage");

ClipboardPage threadPage = tools.getThread().getThreadPage();
threadPage.putString("pyHTMLFrame", "");

tools.putParamValue("MessageHeader", "Report Definition Error");
tools.putParamValue("MessageType" , "Fail");
tools.putParamValue("Message", strError);

String stream = tools.getStream(keys, null);
if (stream != null) {
     threadPage.putString("pxHTMLStream", stream);
} 

myStepPage.removeFromClipboard();

nextBlock = "****Exit Activity****";

String strViewClass = tools.findPage("TempReportPage").getString(".pyClassName");
String strViewClassParam = tools.getParamValue("pyReportClass");

ClassDefinition cd = tools.getDatabase().getClassDef(strViewClass);
ClassDefinition cdParam = tools.getDatabase().getClassDef(strViewClassParam);

if (cd != null)
{
	//replace the classname irrespective of the class on RD being a abstract class. 

                     if(cdParam != null && cdParam.isConcrete()){
                         tools.findPage("TempReportPage").putString("pyClassName",strViewClassParam);
                         //required for the case when we are not using copyProperties for new report.
                         myStepPage.putString("pyClassName", strViewClassParam);
                        }

}
